import { classifyOperationPoll, getOperation } from './operations.js';
export async function getOperationStateInfo(options) {
    const { stackId, operationId, auth, fetchFn, includeDestroyed, progressNoun } = options;
    const { ok, error, operation, response } = await getOperation({
        stackId,
        operationId,
        auth,
        fetchFn,
        includeDestroyed,
    });
    const httpStatus = response?.status;
    const state = classifyOperationPoll({ ok, httpStatus, operation });
    switch (state) {
        case 'completed':
        case 'failed':
            return {
                state,
            };
        case 'error':
            return {
                state,
                error,
                verboseError: `Could not read ${progressNoun} status (HTTP ${httpStatus ?? 'unknown'}${error ? `: ${error}` : ''})`,
            };
        case 'pending':
            if (httpStatus === 404 || !operation) {
                return {
                    state: 'not_found',
                    verboseError: `Waiting for ${progressNoun} status (HTTP 404); retrying.`,
                };
            }
            else {
                return {
                    state,
                    latestStatus: operation.status,
                    verboseMessage: `${progressNoun} operation status: ${operation.status}.`,
                };
            }
        default:
            throw new Error(`Unexpected poll state: ${state}`);
    }
}
